-- Megaverse in Flames: Soulmancy spells, levels ten to twelve.
-- 10 spells rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~342-megaverse-in-flames-spells-c.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
-- Soulmancy, levels ten to twelve, by the spell list on printed p.91; every level
-- agrees with the description headings (p.100-104), and every list cost agrees
-- with its description's P.P.E. line. Every cost and stat line was read off a
-- render. Names keep the description heading as printed, "(Ritual)" or
-- "(ritual)" included. Soulmancy: Soultwist carries same_spell_as Soultwist
-- (Rifts Book of Magic p.145): same level, cost, range, duration and save.

INSERT OR IGNORE INTO spells (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition, ppe_permanent) VALUES
  ('Soulmancy: Deadly Clots', 10, 100, '100 P.P.E. plus at least 1D6 damage direct to Hit Points as the caster stabs himself in the abdomen', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.100', 'rifts', 'Touch or 10 feet (3 m) per level of experience', 'One melee round per level of the spell caster; the onset is instant and the symptoms and penalties vary by the roll', 'By a percentile roll: 01-30 5D6 direct to Hit Points (M.D. to a Mega-Damage being) and the loss of one melee attack; 31-50 a numbed leg; 51-70 a numbed arm; 71-80 a heart attack doing 1D6x10 to Hit Points (2D4x10 M.D.); 81-90 delirium; 91-95 blindness; 96-00 a stroke doing 1D6x10 to Hit Points (2D4x10 M.D.)', 'Standard; a success means no ill effects. Beings with enhanced Bio-Regeneration are +15% to save vs coma and death', NULL, NULL, 'Forms blood clots inside the victim, and the G.M. rolls percentile for where they lodge. Low rolls bring a sharp pain, 5D6 damage straight to Hit Points and a lost attack. A leg clot halves Spd, cuts combat bonuses by a third and costs one attack; an arm clot (left or right at even odds) leaves the limb useless, halves combat bonuses and costs two attacks, or halves attacks, zeroes bonuses and gives -50% on skills using that hand if it is the dominant one (-15% for the other). A heart attack strips combat bonuses, leaves two attacks, halves P.S. and P.P., slows Spd by 80% and does 1D6x10. Delirium leaves two attacks and half bonuses, -80% on complex skills, no spell casting or psionics, a lost sense of self and a 01-40% chance of not knowing friends. Blindness gives -10 to strike, parry and other combat moves. A stroke paralyses one side and does 1D6x10. Damage that drops Hit Points below zero means a coma until the spell ends, then a save vs coma and death at +40% (sharp pain), +30% (heart) or +35% (stroke), waking with 2D6 Hit Points. Every effect ends with the duration. Body armor does not protect, but power armor and sealed M.D.C. vehicles and robots do; vampires, Elementals, creatures of magic and bloodless beings are immune. River of Blood cures it at once.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Demon Heart (Ritual)', 10, 213, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.101-102', 'rifts', 'Touch', 'Indefinite', NULL, 'None for a willing subject; an unwilling victim saves at +2. A success stops the ritual, spends the P.P.E. and does 2D6 damage (Hit Points or M.D.C.) to the one who saved; the Soulmancer must start over with another subject or wait 24 hours to retry', NULL, 'Ritual of 15 minutes, usually with blood sacrifices to raise the P.P.E.', 'Trades the heart of a mortal with the heart of a Lesser or Greater Demon: the Soulmancer reaches into each chest, pulls the beating hearts and seats each in the other body, leaving blood but no wound or scar. The mortal gains half the demon''s M.D.C. and all its Natural Abilities, psionics and I.S.P., but none of its attributes, bonuses or magic; he still looks and bleeds like a mortal from minor cuts, sensing and See Aura reveal nothing, and the demonic M.D.C. and Bio-Regeneration wake only once an injury reaches 20 points or his life is threatened. The demon loses half its M.D.C. and every Natural Ability and psionic power, and is troubled by human feelings it has never known. An unwilling Unprincipled or good recipient need not serve anyone, but the heart corrupts him: one alignment step down after 1D4 months and temptation from the start, and the drop stays after a restoration. Any Soulmancer can swap the hearts back if both are present; the death of either restores the survivor, and a Restoration spell undoes the swap 01-66% of the time. Blood Warriors, Soulmancers and creatures of magic cannot receive one, and only a demon''s heart will serve, never a Deevil''s or an angel''s.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Soul Guard', 10, 55, '55 as a spell or 345 as a ritual', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.101', 'rifts', 'Self or one other by touch; up to three people as a ritual', 'Five minutes per level of experience as a spell, or one week per level of experience as a ritual', NULL, 'Standard, for one who chooses to resist', NULL, 'Spell or ritual', 'Hides the recipient''s life essence in a dimensional limbo, tied to his body the way an astral traveller''s silver thread is, so nothing can consume his soul or tear it from him while it lasts, not even the bite of a vampire that would make him one. The price is that he has no aura and reads as undead, and his P.B. is halved because he looks haggard and close to death though he feels well. A Permanency spell makes both drawbacks permanent along with the protection.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Heart Strings (Ritual)', 11, 375, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.102', 'rifts', 'Touch', 'Indefinite', 'Each M.D. point done to the removed heart costs the victim 5% of his Hit Points (or M.D.C.); destroying the heart (one M.D.C. per point of the victim''s P.E.) kills him wherever he is', '16 or higher, with bonuses vs magic; none for a willing subject or one bargaining. A success ends the ritual with the P.P.E. spent and no harm; retry needs another subject or a 24-hour wait', NULL, 'Ritual only, 30 minutes', 'The Soulmancer lifts out the victim''s still-beating heart and keeps it in a box, on a shelf or anywhere he likes, and the victim goes on living, which makes it a tool of torture and blackmail. Whoever holds the heart holds his life: harming it drains him, and destroying it kills him even across dimensions. Without his heart he cannot become undead or be possessed, gains +3 vs disease and heals twice as fast, but loses one attack per melee round and 20% of his Spd and tires in half the time; when fatigued his attacks and Spd are halved until he rests 1D4+1 minutes. A heart destroyed makes the fatigue permanent, he tires at a tenth the normal rate, and he dies after 8 hours per P.E. point, beyond Restoration or Resurrection unless pieces of the heart are recovered. The original caster can return the heart at any time; another Soulmancer needs a new ritual and the right heart, since a wrong one does 1D4x10 per melee round until it is replaced. Restored, the victim is at once back to full strength. Mortals only, and the victim must have a heart; a Blood Oath binding the caster to give it back is advised for a willing bargain.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Rip Soul', 11, 300, '300 as a spell or 750 as a ritual', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.102-103', 'rifts', 'Touch, holding a few drops of the victim''s blood', 'On a failed save the soul is held for one melee round per level of the spell caster; unless it is put in a vessel such as a Soul Crystal or consumed by then, it returns to its body', NULL, 'Standard vs Soul Drink, 14 or higher; 16 as a ritual. A success means no harm and immunity to the spell for 24 hours, and the victim knows what was tried', NULL, 'Spell or ritual', 'Tears the life essence out of a living, sentient being, much as the soul-drinking power of the greatest Rune Weapons does. The caster must first draw the target''s blood and hold a few drops of it, then touch him. The emptied body falls into a coma and wastes away without life support, recovering only if the soul comes back. The capture is temporary: before the duration ends the caster must move the soul into a Soul Crystal or similar container, or turn it into P.P.E. or I.S.P., or it flies home and the victim leaps up awake. Someone who survives it cannot be targeted again for 24 hours.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Suspend Soul (Ritual)', 11, 150, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.103', 'rifts', 'Touch', 'Indefinite', NULL, 'None', NULL, 'Ritual', 'Keeps a captured life essence indefinitely by placing it in a temporary or permanent vessel such as a Soul Crystal or Soul Gem, or moves one from one such vessel to another; it underlies the making of demonic and Rune weapons, Splugorth Bio-Wizard devices and other soul-powered items. Once a soul is sealed into a permanent vessel such as a Rune weapon or Bio-Wizard device, neither this nor any other spell can take it back out. It can, however, gather, move or free the souls held as fuel by Deevil or demonic weapons and war machines. A freed soul seeks its body and wakes it from its coma, or passes on if the body is dead. The mind travels with the soul, so the body lies comatose and wastes away until the soul returns.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Soul Body (Ritual)', 12, 275, '275 P.P.E. plus one soul held in a Soul Crystal', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.103', 'rifts', 'Touch', 'Instant, lasting five decades; once per individual every 50 years, and the boost fades just before the 50th anniversary', NULL, 'None; the consumed soul is already held in a Soul Crystal and has no save', NULL, 'Ritual only', 'Burns a captured life essence to strengthen another being''s body. The recipient is rejuvenated: a crippling disease or infirmity is set back to its beginning (it may return in time), he seems 1D6+8 years younger in looks and in how he feels, and one physical attribute of his choice rises by an amount set by the soul used: an evil human or D-Bee 1 point; a good human or D-Bee, any faerie folk, or a sub-demon, host, lesser supernatural being or demigod 2; a selfish or evil powerful creature of magic 3; a good powerful creature of magic such as a dragon, sphinx or Elemental, or a greater supernatural being or godling 4; a deific being 10. Undead and a god''s avatar cannot be used. The soul is destroyed for good.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Soul Mind (Ritual)', 12, 275, '275 P.P.E. plus one soul held in a Soul Crystal', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.103-104', 'rifts', 'Touch', 'Instant, lasting five decades; once per individual every 50 years, and the boost fades just before the 50th anniversary', NULL, 'None; the consumed soul is already held in a Soul Crystal and has no save', NULL, 'Ritual only', 'The mental twin of Soul Body: a captured life essence is consumed to sharpen another being''s mind. Dementia or brain disease is set back to its beginning (it may return in time), though insanities remain; the recipient gains +1 to Perception Rolls, and one mental attribute of his choice rises by the same amounts as Soul Body: an evil human or D-Bee 1 point; a good human or D-Bee, any faerie folk, or a sub-demon, host, lesser supernatural being or demigod 2; a selfish or evil powerful creature of magic 3; a good powerful creature of magic or a greater supernatural being or godling 4; a deific being 10. Undead and a god''s avatar cannot be used, and the soul is destroyed for good.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Soultwist', 12, 170, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.104', 'rifts', '100 feet (30.5 m); line of sight or touch', 'Doubt and temptation for at least 3D4 weeks; the physical damage is instant', '6D6 M.D. to a Mega-Damage creature, or direct to Hit Points for a mortal S.D.C. being', '-6 to save; a success means no physical damage and only minor doubt and reevaluation', NULL, NULL, 'Strikes both body and spirit. The physical damage cannot be healed by ordinary means; only a priest, god or divine servant of the appropriate faith or ethics can restore it. Worse, the victim is filled with doubt about his beliefs, morals, gods and alignment and suddenly sees the opposite view: good characters consider evil, lies and cheating, while evil characters find conscience and compassion. The spell forces no action or change; whether the temptation alters the character''s alignment is left to the player and the G.M., and returning to old ways afterward takes months or years of effort.', 'Soultwist', 'soulmancy', NULL),
  ('Soulmancy: Supernatural Soul (ritual)', 12, 220, '220 P.P.E. plus the soul of a Lesser or Greater Demon', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.104-105', 'rifts', 'Self or another by touch and ritual', 'One week; indefinite if a life essence is consumed every three days', NULL, 'Standard, for one who chooses to resist', NULL, 'Ritual', 'Spends a captured demon soul (Lesser or Greater) to give the caster or one mortal the powers of a supernatural being for a week. The recipient becomes a Mega-Damage being with M.D.C. equal to 100 plus his Hit Points and S.D.C. (an M.D.C. being adds 200 instead); he adds 1D6 to P.S. and Spd, his P.S. and P.E. become Supernatural, and he gains half damage from fire, Nightvision 100 feet (30.5 m), the power to see the invisible, understanding and speech of every language, Bio-Regeneration at 1D4 M.D.C. each melee round, +1 attack per melee round and +1 to Perception Rolls. A black nimbus shows in his aura and around him whenever he is angry or fighting, and while it shows his Horror Factor is 13, or one higher than any he already had. He can keep the power only by becoming a life energy vampire, killing a sentient being and feeding on its blood and dying P.P.E. at least every three days; choosing that turns him Miscreant, and Permanency will not hold it.', NULL, 'soulmancy', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 10 spells rows are in' AS assertion, count(*) AS got, 10 AS want
  FROM spells WHERE name IN ('Soulmancy: Deadly Clots', 'Soulmancy: Demon Heart (Ritual)', 'Soulmancy: Soul Guard', 'Soulmancy: Heart Strings (Ritual)', 'Soulmancy: Rip Soul', 'Soulmancy: Suspend Soul (Ritual)', 'Soulmancy: Soul Body (Ritual)', 'Soulmancy: Soul Mind (Ritual)', 'Soulmancy: Soultwist', 'Soulmancy: Supernatural Soul (ritual)') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~342-megaverse-in-flames-spells-c.sql');
